using System;
using System.IO;
using System.Linq;
using System.Runtime.Versioning;
using System.Threading;
using System.Threading.Tasks;
using SftpSync.Core;

namespace SftpSync.Services
{
    [SupportedOSPlatform("windows")]
    public class SyncEngine
    {
        private readonly ConfigService _configService;
        private readonly SftpService _sftpService;
        private FileSystemWatcher? _watcher;

        public SyncEngine()
        {
            _configService = new ConfigService();
            _sftpService = new SftpService();
        }

        /// <summary>
        /// Démarre la surveillance du premier dossier actif trouvé dans les règles.
        /// (Pour simplifier cette étape, on surveille une règle active).
        /// </summary>
        public void Start()
        {
            var activeRule = _configService.GetRules().FirstOrDefault(r => r.IsEnabled);
            if (activeRule == null) return;

            if (!Directory.Exists(activeRule.LocalFolder)) return;

            // Configuration du surveillant de dossier Windows
            _watcher = new FileSystemWatcher(activeRule.LocalFolder, activeRule.FileFilter)
            {
                NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite,
                EnableRaisingEvents = true
            };

            // On s'abonne à l'événement : "Un nouveau fichier est apparu"
            _watcher.Created += (sender, e) => OnFileDetected(e.FullPath, activeRule);
        }

        public void Stop()
        {
            if (_watcher != null)
            {
                _watcher.EnableRaisingEvents = false;
                _watcher.Dispose();
            }
        }

        private void OnFileDetected(string localFilePath, SyncRule rule)
        {
            // On exécute le traitement en arrière-plan pour ne pas bloquer l'application
            Task.Run(async () =>
            {
                // 1. On attend que le fichier soit complètement écrit et libéré par Windows
                if (!WaitForFileReady(localFilePath))
                {
                    // Fichier toujours verrouillé après plusieurs tentatives, on abandonne pour cette fois
                    return;
                }

                // 2. On récupère la configuration SFTP associée à la règle
                var connection = _configService.GetConnections().FirstOrDefault(c => c.Id == rule.ConnectionId);
                if (connection == null) return;

                // 3. On tente le transfert SFTP Atomique (.tmp puis renommer)
                bool transferSuccess = await _sftpService.UploadFileAtomicAsync(connection, localFilePath, rule.RemoteFolder);

                // 4. Gestion Post-Transfert (Exigence n°3)
                if (transferSuccess)
                {
                    HandlePostTransferSuccess(localFilePath, rule);
                }
                else
                {
                    // En cas d'échec, le fichier reste en place pour une prochaine tentative
                }
            });
        }

        /// <summary>
        /// Boucle de vérification : Attend que le fichier ne soit plus en cours d'écriture.
        /// </summary>
        private bool WaitForFileReady(string filePath)
        {
            int maxAttempts = 10;
            int delayMilliseconds = 1000; // Attend 1 seconde entre chaque vérification

            for (int i = 0; i < maxAttempts; i++)
            {
                try
                {
                    // Si on arrive à ouvrir le fichier exclusivement, il est prêt !
                    using (FileStream stream = File.Open(filePath, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
                    {
                        return true; 
                    }
                }
                catch (IOException)
                {
                    // Le fichier est encore verrouillé par une autre application (écriture en cours...)
                    Thread.Sleep(delayMilliseconds);
                }
            }
            return false;
        }

        /// <summary>
        /// Gère le fichier local après un envoi réussi (Suppression ou Archivage).
        /// </summary>
        private void HandlePostTransferSuccess(string filePath, SyncRule rule)
        {
            try
            {
                if (rule.ArchiveAfterSend && !string.IsNullOrEmpty(rule.ArchiveFolder))
                {
                    if (!Directory.Exists(rule.ArchiveFolder))
                    {
                        Directory.CreateDirectory(rule.ArchiveFolder);
                    }

                    string destinationPath = Path.Combine(rule.ArchiveFolder, Path.GetFileName(filePath));
                    
                    // Si le fichier existe déjà dans l'archive, on le supprime avant de déplacer
                    if (File.Exists(destinationPath)) File.Delete(destinationPath);

                    File.Move(filePath, destinationPath);
                }
                else
                {
                    // Option par défaut : Suppression brute
                    File.Delete(filePath);
                }
            }
            catch
            {
                // Gestion silencieuse des erreurs d'archivage pour éviter le crash du moteur
            }
        }
    }
